"use strict";

var unbound = require("./unbound");

var slice = unbound([Array.prototype.slice]);
var join = unbound([Array.prototype.join]);
var owns = unbound([Object.prototype.hasOwnProperty]);
var tag = unbound([Object.prototype.toString]);
var total = unbound([
  function (a, b) {
    return this.base + a + b;
  },
  { base: 1 },
]);

exports.report = function () {
  var lines = [];
  lines.push(JSON.stringify(slice([1, 2, 3, 4], 1, 3)));
  lines.push(join(["cup", "spoon", "ladle"], " + "));
  lines.push(String(owns({ cup: 1 }, "cup")) + " " + String(owns({ cup: 1 }, "spoon")));
  lines.push(tag([]) + " " + tag(null));
  lines.push(String(total(2, 3)));
  lines.push(typeof slice + " " + typeof total);
  try {
    unbound([]);
  } catch (e) {
    lines.push(e.name + ": " + e.message);
  }
  try {
    unbound(["ladle"]);
  } catch (e) {
    lines.push(e.name + ": " + e.message);
  }
  return lines;
};
